function failedCheck(name: string, threshold: string, reason: string): CheckResult {
  return {
    name,
    passed: false,
    value: 'error',
    threshold,
    samples: [{ error: reason }],
  };
}

async function safeCheck(
  name: string,
  threshold: string,
  fn: () => Promise<CheckResult[]>,
): Promise<CheckResult[]> {
  try {
    return await fn();
  } catch (err) {
    return [failedCheck(name, threshold, (err as Error).message)];
