        )
        .orderBy(desc(scraperLogs.startedAt))
        .limit(10);
      samples = sampleRows;
    }

    results.push({
      name: `${svc.key}_failure_rate_6h`,
      passed,
      value: `${failed}/${total} (${failRate}%)`,
      threshold: '≤ 3 failures',
      samples,
    });
