export type { TimezoneCheckResult } from './time';

export type DbClient = ReturnType<typeof drizzle<typeof schema>>;

let _db: DbClient | null = null;

export function getDb(): DbClient {
  if (_db) return _db;
  const url = process.env.DATABASE_URL;
  if (!url) throw new Error('DATABASE_URL is not set');
  // Keep pool small per-service so 6 services don't exhaust PostgreSQL's
  // default max_connections (typically 100). Each service gets up to 5
  // connections; peak total = 30, leaving headroom for admin tools.
  const pool = new Pool({
    connectionString: url,
    max: 5,
    idleTimeoutMillis: 30_000,
    connectionTimeoutMillis: 5_000,
  });
  // Enforce UTC session timezone on every connection so that TIMESTAMP WITHOUT TZ
  // values written by pg are stored as UTC wall-clock, consistent with TZ=UTC containers.
  pool.on('connect', (client) => { client.query("SET TIME ZONE 'UTC'").catch(() => {}); });
  _db = drizzle(pool, { schema });
  return _db;
}

// Proxy-based `db` export — lazily initialises the pool on first use.
// Only import this from server-side code (*.server.ts / Node scrapers).
export const db: DbClient = new Proxy({} as DbClient, {
  get(_t, prop) {
    return (getDb() as unknown as Record<string | symbol, unknown>)[prop];
  },
  apply(_t, _this, args) {
    return (getDb() as unknown as (...a: unknown[]) => unknown)(...args);
  },
});

import { config } from 'dotenv';
import { resolve, dirname } from 'path';
import { existsSync } from 'fs';

/**
 * Walks up from the start directory to find a .env file.
 * Works for ts-node (src/) and compiled output.
 * @param startDir - The directory to start searching from
 * @returns The path to the .env file, or null if not found
 */
export function findEnvFile(startDir: string): string | null {
  let dir = startDir;
  for (let i = 0; i < 10; i++) {
    const candidate = resolve(dir, '.env');
    if (existsSync(candidate)) return candidate;
    const parent = dirname(dir);
    if (parent === dir) break;
    dir = parent;
  }
  return null;
}

export interface LoadEnvOptions {
  /** The service name for logging (e.g., 'guernsey', 'fr24') */
  serviceName: string;
  /** The directory to start searching from (defaults to __dirname) */
  startDir?: string;
  /** Whether to log the env file path when found */
  logPath?: boolean;
}

/**
 * Loads environment variables from a .env file found by walking up directories.
 * @param options - Configuration options for loading the env file
 */
export function loadEnv(options: LoadEnvOptions): void {
  const { serviceName, startDir = process.cwd(), logPath = false } = options;
  const envPath = findEnvFile(startDir);

  if (envPath) {
    config({ path: envPath });
    if (logPath) {
      console.log(`[${serviceName}] Loaded env from ${envPath}`);
    }
  } else {
    console.warn(`[${serviceName}] Warning: .env file not found, relying on environment variables`);
  }
}

